code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            q = [(r, c)]
            seen.add((r, c))
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            y0, y1 = min(y for y,x in cells), max(y for y,x in cells)
            x0, x1 = min(x for y,x in cells), max(x for y,x in cells)
            # A shape is hollow when its bounding box contains an enclosed zero.
            outside = set()
            flood = deque()
            for yy in range(y0, y1+1):
                for xx in (x0, x1):
                    if (yy, xx) not in cells and (yy, xx) not in outside:
                        outside.add((yy, xx)); flood.append((yy, xx))
            for xx in range(x0, x1+1):
                for yy in (y0, y1):
                    if (yy, xx) not in cells and (yy, xx) not in outside:
                        outside.add((yy, xx)); flood.append((yy, xx))
            while flood:
                yy, xx = flood.popleft()
                for ny, nx in ((yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)):
                    if y0 <= ny <= y1 and x0 <= nx <= x1 and (ny,nx) not in cells and (ny,nx) not in outside:
                        outside.add((ny,nx)); flood.append((ny,nx))
            hollow = any((yy, xx) not in cells and (yy, xx) not in outside
                         for yy in range(y0, y1+1) for xx in range(x0, x1+1))
            objects.append({'cells': cells, 'color': color, 'y0': y0, 'x0': x0, 'hollow': hollow})

    result = [[0] * w for _ in range(h)]
    for direction in (1, -1):  # hollow objects rise; solid objects fall
        group = [o for o in objects if o['hollow'] == (direction == 1)]
        group.sort(key=lambda o: (o['y0'], o['x0']), reverse=(direction == -1))
        placed = []
        for obj in group:
            cells = obj['cells']
            dy = 0
            while True:
                ndy = dy - 1 if direction == 1 else dy + 1
                moved = {(y+ndy, x) for y, x in cells}
                if any(y < 0 or y >= h for y, x in moved):
                    break
                if any(moved & prev for prev in placed):
                    break
                dy = ndy
            shifted = {(y+dy, x) for y, x in cells}
            placed.append(shifted)
            for y, x in shifted:
                result[y][x] = obj['color']
    return result
'''
